  var TAGS = { bp:"BP-friendly", fiber:"High fiber", fish:"Fish", plant:"Plant-based", prep:"Sabbath prep-ahead", desalt:"Desalt first", ackee:"Ackee", shell:"Shellfish" };

  root.JM_DATA = { RECIPES: R, CUISINES: CUISINES, SECTIONS: SECTIONS, TAGS: TAGS, DESALT: DESALT };
